import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.NkyI2htt.js";const s="/cours/assets/05-dates-5.Cg0gOB_O.png",i="/cours/assets/05-dates.D5QGfNfc.png",r="/cours/assets/05-dates-1.BX7Ek2gK.png",c="/cours/assets/05-dates-2.DkYRvjGf.png",d="/cours/assets/05-dates-3.H_0wg5X4.png",l="/cours/assets/05-dates-4.BWS9N5Hi.png",x=JSON.parse('{"title":"Fonctions de date","description":"","frontmatter":{"title":"Fonctions de date"},"headers":[],"relativePath":"modules/02-excel/05-fonctions-date.md","filePath":"modules/02-excel/05-fonctions-date.md"}'),u={name:"modules/02-excel/05-fonctions-date.md"};function m(p,e,h,f,g,_){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="fonctions-de-date" tabindex="-1">Fonctions de date <a class="header-anchor" href="#fonctions-de-date" aria-label="Permalink to &quot;Fonctions de date&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p><a href="https://livecegepfxgqc-my.sharepoint.com/:x:/g/personal/otremblay_cegepgarneau_ca/IQD5biM3pyoiTKh1B1NGwKH9Afx4LnP_KL1jcuqNDMieI58?e=V23UDD" target="_blank" rel="noreferrer">05 – Fonctions de date</a></p><p>⚠️ Ne travaillez pas dans la version Excel du navigateur Web.</p><p><strong>Veuillez télécharger une copie de chaque exercice.</strong></p><ul><li>Fichier --&gt; Créer une copie --&gt; Télécharger une copie</li></ul><h2 id="dates-dans-excel" tabindex="-1">Dates dans Excel <a class="header-anchor" href="#dates-dans-excel" aria-label="Permalink to &quot;Dates dans Excel&quot;">​</a></h2><p>Les dates sont des constantes numériques. On additionne 1 à tous les jours depuis le 1er janvier 1900.</p><p>ex.: <code>23 mai 2025</code> (format date longue) = <code>45800</code> (format standard = nombre de jours depuis 1er janvier 1900)</p><h2 id="format-de-cellule-des-dates" tabindex="-1">Format de cellule des dates <a class="header-anchor" href="#format-de-cellule-des-dates" aria-label="Permalink to &quot;Format de cellule des dates&quot;">​</a></h2><ul><li><strong>Standard</strong> : Affiche la date en tant que nombre de jours depuis 1er janvier 1900</li><li><strong>Date</strong> : format recommandé. Affiche correctement une valeur de date selon les paramètres régionaux.</li><li><strong>Personnalisé</strong> : permet de contrôler précisément l’affichage (ex. <code>aaaa-mm-jj</code>, <code>jj/mm/aaaa</code>).</li></ul><img src="'+s+'" alt="Date" class="img-bordered"><h2 id="fonction-aujourdhui" tabindex="-1">Fonction AUJOURDHUI() <a class="header-anchor" href="#fonction-aujourdhui" aria-label="Permalink to &quot;Fonction AUJOURDHUI()&quot;">​</a></h2><p>Retourne dynamiquement la date courrante.</p><h2 id="fonction-date" tabindex="-1">Fonction DATE <a class="header-anchor" href="#fonction-date" aria-label="Permalink to &quot;Fonction DATE&quot;">​</a></h2><p>Crée une date à partir de valeurs numériques.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=DATE(annee; mois; jour)</span></span></code></pre></div><img src="'+i+'" alt="Date" class="img-bordered"><img src="'+r+'" alt="Date" class="img-bordered mt-5"><h2 id="fonctions-jour-mois-et-annee" tabindex="-1">Fonctions JOUR, MOIS et ANNEE <a class="header-anchor" href="#fonctions-jour-mois-et-annee" aria-label="Permalink to &quot;Fonctions JOUR, MOIS et ANNEE&quot;">​</a></h2><p>Extraient une partie d&#39;une date.</p><ul><li>JOUR(A1)</li><li>MOIS(A1)</li><li>ANNEE(A1)</li></ul><img src="'+c+'" alt="Date" class="img-bordered"><h2 id="fonction-fin-mois" tabindex="-1">Fonction FIN.MOIS <a class="header-anchor" href="#fonction-fin-mois" aria-label="Permalink to &quot;Fonction FIN.MOIS&quot;">​</a></h2><p>Retourne le dernier jour d&#39;un mois.</p><ul><li>FIN.MOIS(A1; 0) : fin du mois courant</li><li>FIN.MOIS(A1; 1) : fin du mois suivant</li><li>FIN.MOIS(A1; -1) : fin du mois précédent</li></ul><blockquote><p>Dans l&#39;exemple ci-bas, mois_courrant - mois_précédent nous retourne le nombre de jours dans le mois courrant. (B25 = 23 mai 2025)</p></blockquote><img src="'+d+'" alt="Date" class="img-bordered"><h2 id="fonction-joursem-date" tabindex="-1">Fonction JOURSEM(date) <a class="header-anchor" href="#fonction-joursem-date" aria-label="Permalink to &quot;Fonction JOURSEM(date)&quot;">​</a></h2><p>Retourne le jour de la semaine en format numérique (1=Dimanche, 7=Samedi)</p><img src="'+l+'" alt="Date" class="img-bordered">',31)])])}const q=a(u,[["render",m]]);export{x as __pageData,q as default};
